solution:
#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);

    for (int row = 1; row <= n; row++) {
        for (int space = 0; space < n - row; space++) {
            putchar(' ');
        }
        for (int number = 1; number <= row; number++) {
            printf("%d", number);
        }
        for (int number = row - 1; number >= 1; number--) {
            printf("%d", number);
        }
        putchar('\n');
    }

    return 0;
}

