#include <stdio.h>

int main(void) {
    int amount;
    scanf("%d", &amount);

    int coins[] = {25, 10, 5, 1};
    int totalCoins = 0;

    for (int i = 0; i < 4; i++) {
        int count = amount / coins[i];
        amount %= coins[i];
        totalCoins += count;
        printf("%d: %d\n", coins[i], count);
    }

    printf("Total: %d\n", totalCoins);
    return 0;
}

